// Generated by scripts/local_models_contract.py from the JSON schema of the
// agent service's local model list and local engine answers, which the host
// passes on unchanged; do not edit. Regenerate with
// `node scripts/local-models-contract.mjs`; `--check` fails when it is stale.

/**
 * The engine that runs models on this computer.
 */
export type LocalEngine = "llamacpp" | "ollama";

/**
 * The tokens a person may choose for the local engine setting, each in the
 * order its enum declares them.
 */
export type LocalEngineChoices = {
  engine: LocalEngine[];
  placement: LocalPlacement[];
};

/**
 * The local engine setting: the engine that runs models on this computer and
 * where it runs them.
 *
 * It is kept in the model list record, so `revision` is that record's guard
 * and a change to either sends it back. An absent record, or one holding no
 * choice, reads as the default engine and placement with `chosen` false;
 * `chosen` is true only for a setting the person stored, which the default
 * never overrules. `unreadable` means the stored record cannot be read: then
 * no engine or placement is known and none is assumed, and `revision` guards
 * the reset that removes the record. `choices` is the closed list a frontend
 * renders its pickers from. It is computed from the enums every request is
 * validated against, so a frontend never holds a copy and a status cannot
 * carry a different list.
 */
export type LocalEngineStatus = {
  unreadable: boolean;
  chosen: boolean;
  engine: LocalEngine | null;
  placement: LocalPlacement | null;
  revision: string;
  /**
   * The engines and placements that can be chosen, in declared order.
   */
  choices: LocalEngineChoices;
};

/**
 * One lane and one of its models: a model added to a local lane's list, or the
 * model read with.
 */
export type LocalModelListEntry = {
  lane: string;
  model: string;
};

/**
 * The models the person added to local lanes' lists, in the order added, with
 * the record's guard.
 *
 * A lane's recommended models are the catalogue's and are not listed here.
 * `reading` is the lane and model documents are read with now, and
 * `reading_source` says where it comes from: the person's stored choice
 * (`chosen`), the default that stands in when no stored choice is usable
 * (`default`, never written to the record), or `none`, when `reading` is
 * `None`. Every reading of a document uses this same selection. `local_lanes`
 * are the catalogue's local lane ids, whose models a picker offers from their
 * lists; none when the catalogue cannot be read. `tasks` are the settings the
 * person stored per task kind, in the order stored; a kind without one runs on
 * `reading`. `unreadable` means a stored list record cannot be read. Then no
 * model is listed or selected, because nothing is known, and `revision` guards
 * the reset that removes the record. Every state carries a revision, so an
 * unreadable record always has a reset route.
 */
export type LocalModelListStatus = {
  unreadable: boolean;
  models: LocalModelListEntry[];
  reading: LocalModelListEntry | null;
  reading_source: ReadingSource;
  tasks: TaskModelEntry[];
  local_lanes: string[];
  revision: string;
};

/**
 * Where the local engine runs a model: on a graphics device when the load
 * fits, or on the processor only.
 */
export type LocalPlacement = "auto" | "cpu_only";

/**
 * Where the model documents are read with comes from.
 */
export type ReadingSource = "chosen" | "default" | "none";

/**
 * The lane, model and effort the person set for one task kind.
 *
 * `task_kind` is the agent's id for the kind, from its served catalogue.
 * `effort` is `None` when the person set none, and the run then names no
 * effort. A kind with no entry runs on the model documents are read with.
 */
export type TaskModelEntry = {
  task_kind: string;
  lane: string;
  model: string;
  effort: string | null;
};
